def check(markers, fills, H, W):
    ms = set(markers)
    pred = set()
    for i in range(H):
        row = sorted(j for (r,j) in ms if r==i)
        for a,b in zip(row,row[1:]):
            for j in range(a+1,b): pred.add((i,j))
    for j in range(W):
        col = sorted(i for (i,c) in ms if c==j)
        for a,b in zip(col,col[1:]):
            for i in range(a+1,b): pred.add((i,j))
    return pred == fills, pred-fills, fills-pred
