def pairs(g, c):
    H,W=len(g),len(g[0]); row_p=[]; col_p=[]
    M={(i,j) for i in range(H) for j in range(W) if g[i][j]==c}
    for i in range(H):
        js=sorted(j for (r,j) in M if r==i)
        row_p += [(i,a,b) for a,b in zip(js,js[1:])]
    for j in range(W):
        is_=sorted(i for (i,cc) in M if cc==j)
        col_p += [(a,j,b) for a,b in zip(is_,is_[1:])]
    return row_p,col_p
