def mst_fill(g,c,H,W):
    M=sorted({(i,j) for i in range(H) for j in range(W) if g[i][j]==c})
    n=len(M); idx={p:k for k,p in enumerate(M)}
    edges=[]
    for x in range(n):
        for y in range(x+1,n):
            (i1,j1),(i2,j2)=M[x],M[y]
            if i1==i2 or j1==j2:
                # must be consecutive? allow any; interior fill includes cells that may contain markers
                edges.append((abs(i1-i2)+abs(j1-j2),x,y))
    parent=list(range(n))
    def find(a):
        while parent[a]!=a: parent[a]=parent[parent[a]]; a=parent[a]
        return a
    edges.sort(); fills=set(); chosen=[]
    for w,x,y in edges:
        rx,ry=find(x),find(y)
        if rx!=ry:
            parent[rx]=ry; chosen.append((M[x],M[y]))
            (i1,j1),(i2,j2)=M[x],M[y]
            if i1==i2:
                fills|={(i1,j) for j in range(min(j1,j2)+1,max(j1,j2))}
            else:
                fills|={(i,j1) for i in range(min(i1,i2)+1,max(i1,i2))}
    return fills,chosen
