def seg_graph(g,c,H,W,fills):
    M={(i,j) for i in range(H) for j in range(W) if g[i][j]==c}
    adj={p:set() for p in M}
    rsegs,csegs=pairs(g,c)
    for (i,a,b) in rsegs:
        if cells(i,a,b) <= fills:
            adj[(i,a)].add((i,b)); adj[(i,b)].add((i,a))
    for (i,j,b) in csegs:
        if cellsC(i,j,b) <= fills:
            adj[(i,j)].add((b,j)); adj[(b,j)].add((i,j))
    return adj
