        for a,b in zip(js,js[1:]): edges[((i,a),(i,b))]=b-a
    for j in range(W):
        is_=sorted(i for p in M if p[1]==j)
        for a,b in zip(is_,is_[1:]): edges[((a,j),(b,j))]=b-a
    # Kruskal by weight groups; within a group, union all edges connecting different comps of current forest
    parent={p:p for p in M}
    def find(a):
        while parent[a]!=a: parent[a]=parent[parent[a]]; a=parent[a]
        return a
    chosen=set()
    from collections import defaultdict
    byw=defaultdict(list)
    for e,w in edges.items(): byw[w].append(e)
    for w in sorted(byw):
        grp=byw[w]; base={p:find(p) for p in M}
        used=[]
        for (u,v) in grp:
            ru,rv=base[u],base[v]
            if ru!=rv:
                used.append((u,v)); chosen.add((u,v))
        for (u,v) in used:
            ru,rv=find(u),find(v)
            if ru!=rv: parent[ru]=rv
    fills=set()
    for (u,v) in chosen:
        (i1,j1),(i2,j2)=u,v
        if i1==i2: fills|={(i1,j) for j in range(min(j1,j2)+1,max(j1,j2))}
        else: fills|={(i,j1) for i in range(min(i1,i2)+1,max(i1,i2))}
    return chosen,fills
