        for a,b in zip(ii,ii[1:]): edges[((a,j),(b,j))]=b-a
    parent={p:p for p in M}
    def find(a):
        while parent[a]!=a: parent[a]=parent[parent[a]]; a=parent[a]
        return a
    chosen=set()
    from collections import defaultdict
    byw=defaultdict(list)
    for e,w in edges.items(): byw[w].append(e)
    for w in sorted(byw):
        grp=byw[w]; base={p:find(p) for p in M}
        used=[]
        for (u,v) in grp:
            if base[u]!=base[v]: used.append((u,v))
        chosen.update(used)
        for (u,v) in used:
            ru,rv=find(u),find(v)
