def mst_edges(M,H,W):
    edges={}
    for i in range(H):
        jj=sorted(p[1] for p in M if p[0]==i)
        for a,b in zip(jj,jj[1:]): edges[((i,a),(i,b))]=b-a
    for j in range(W):
        ii=sorted(p[0] for p in M if p[1]==j)
        for a,b in zip(ii,ii[1:]): edges[((a,j),(b,j))]=b-a
    parent={p:p for p in M}
    def find(a):
        while parent[a]!=a: parent[a]=parent[parent[a]]; a=parent[a]
        return a
    chosen=[]
    for e,w in sorted(edges.items(), key=lambda kv: kv[1]):
        u,v=e; ru,rv=find(u),find(v)
        if ru!=rv: parent[ru]=rv; chosen.append((e,w))
    return chosen, edges
